```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract ComplexSmartContract is ERC20, Ownable, ReentrancyGuard {
    struct Proposal {
        string description;
        uint256 voteCount;
        mapping(address => bool) voted;
    }

    mapping(uint256 => Proposal) public proposals;
    uint256 public proposalCount;
    uint256 public votingPeriod = 7 days;
    uint256 public lastProposalTimestamp;

    event ProposalCreated(uint256 indexed proposalId, string description);
    event Voted(uint256 indexed proposalId, address indexed voter, bool vote);
    event ProposalExecuted(uint256 indexed proposalId, bool executed);

    constructor() ERC20("ComplexSmartContractToken", "CSC") {}

    function createProposal(string memory _description) public onlyOwner {
        Proposal storage proposal = proposals[proposalCount];
        proposal.description = _description;
        proposal.voteCount = 0;
        proposalCount++;
        lastProposalTimestamp = block.timestamp;
        emit ProposalCreated(proposalCount - 1, _description);
    }

    function vote(uint256 _proposalId, bool _vote) public nonReentrant {
        Proposal storage proposal = proposals[_proposalId];
        require(block.timestamp <= lastProposalTimestamp + votingPeriod, "Voting period has ended");
        require(!proposal.voted[msg.sender], "Already voted");

        proposal.voted[msg.sender] = true;
        if (_vote) {
            proposal.voteCount += 1;
        }

        emit Voted(_proposalId, msg.sender, _vote);
    }

    function executeProposal(uint256 _proposalId) public onlyOwner {
        Proposal storage proposal = proposals[_proposalId];
        require(block.timestamp > lastProposalTimestamp + votingPeriod, "Voting period has not ended");
        require(!proposal.executed, "Proposal already executed");

        // Execute proposal logic here (e.g., transfer tokens, change state, etc.)
        proposal.executed = true;

        emit ProposalExecuted(_proposalId, true);
    }

    function mintTokens(uint256 _amount) public onlyOwner {
        _mint(msg.sender, _amount);
    }

    function burnTokens(uint256 _amount) public onlyOwner {
        _burn(msg.sender, _amount);
    }
}
```

This contract includes:
- Token creation using OpenZeppelin's ERC20 standard.
- Proposal creation and voting mechanism.
- Non-reentrant voting to prevent double voting.
- Proposal execution after the voting period ends.
- Minting and burning tokens by the contract owner.

Feel free to modify and expand this contract to suit your specific needs!

